effect.shader:
// Random hash function
float hash12(vec2 p) {
    vec3 p3  = fract(vec3(p.xyx) * .1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

// Sample texture
vec3 getSource(vec2 uv) {
    return texture2DCv(inputImg.texture, uv).rgb;
}

// Get intensity/luma for gradient calculation
float getGray(vec3 c) {
    return dot(c, vec3(0.299, 0.587, 0.114));
}

void main() {
    vec2 uv = acScreenNorm;

    // 1. Grid setup
    // Scale UV by frequency to create a grid
    // Aspect correction ensures square grid cells
    float aspect = acScreenSize.x / acScreenSize.y;
    vec2 scale = vec2(frequency * aspect, frequency);
    vec2 gridUV = uv * scale;
    vec2 gridId = floor(gridUV);

    // 2. Accumulators for painting
    vec3 pixelColor = getSource(uv); // Background base
    float bestPriority = -1.0;

    // 3. Neighbor Loop
    // Check neighboring cells to allow strokes to overlap
    for (float y = -2.0; y <= 2.0; y++) {
        for (float x = -2.0; x <= 2.0; x++) {
            vec2 neighbor = vec2(x, y);
            vec2 id = gridId + neighbor;

            // Randomness Logic
            // If jitter is on (>0.5), we change the seed over time.
            float timeOffset = (jitter > 0.5) ? floor(acTime * 12.0) : 0.0;
            vec2 seed = id + vec2(timeOffset * 0.1, timeOffset * 1.618);

            // Random numbers for this stroke
            vec2 rand = vec2(hash12(seed), hash12(seed + 4.13));

            // Stroke Center (jittered within its grid cell)
            vec2 centerGrid = neighbor + rand; 

            // Sample the source image at the stroke's center position
            vec2 centerUV = (id + rand) / scale;

            // Bounds check for UV sampling
            if (centerUV.x < 0.0 || centerUV.x > 1.0 || centerUV.y < 0.0 || centerUV.y > 1.0) continue;

            vec3 col = getSource(centerUV);

            // Compute Gradient / Orientation at stroke center
            vec2 eps = vec2(2.0 / acScreenSize.x, 2.0 / acScreenSize.y);
            float gC = getGray(col);
            float gH = getGray(getSource(centerUV + vec2(eps.x, 0.0)));
            float gV = getGray(getSource(centerUV + vec2(0.0, eps.y)));
            float dX = gH - gC;
            float dY = gV - gC;

            // Orientation: Perpendicular to gradient (tangent to edges)
            float angle = atan(dY, dX) + 1.5708; // +90 degrees

            // Current pixel position relative to current cell grid (fractional part)
            vec2 p = fract(gridUV); 
            // Vector from stroke center to current pixel
            vec2 delta = p - centerGrid;

            // Rotate delta to align with the stroke direction
            float cs = cos(-angle);
            float sn = sin(-angle);
            vec2 rotP = vec2(delta.x * cs - delta.y * sn, delta.x * sn + delta.y * cs);

            // Stroke SDF (Capsule/Ellipse approximation)
            float len = strokeLength * 0.8; 
            float wid = strokeWidth * 0.3;

            // Distance to line segment
            float dx = max(abs(rotP.x) - len, 0.0);
            float dy = abs(rotP.y);

            // Elliptical distance approx
            float dist = length(vec2(dx, dy));

            // Create Mask (Alpha)
            float mask = 1.0 - smoothstep(wid - 0.1, wid + 0.1, dist);

            // Texture the brush stroke
            float brushNoise = hash12(rotP * 10.0 + seed);
            mask *= 0.8 + 0.2 * brushNoise;

            // Compositing
            if (mask > 0.01) {
                float depth = rand.x; // Random depth 0..1
                float priority = depth * mask; // Weight by opacity

                if (priority > bestPriority) {
                    bestPriority = priority;
                    pixelColor = col;
                    // Slight shading for depth perception
                    pixelColor *= 0.95 + 0.05 * mask;
                }
            }
        }
    }

    gl_FragColor = vec4(pixelColor, 1.0);
}
